begin;
-- Local metadata/financial authority fixture, not proof of uploaded PDF bytes.
create extension if not exists pgtap with schema extensions;select extensions.no_plan();
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) values('e2100000-0000-4000-8000-000000000001','planning-owner@local.invalid'),('e2100000-0000-4000-8000-000000000002','planning-employee@local.invalid');
alter table auth.users enable trigger on_auth_user_created;
insert into public.companies(id,name,operating_timezone,planned_productive_hours_annual,owner_compensation_target_annual,owner_planned_field_hours_annual,owner_field_rate) values('e2200000-0000-4000-8000-000000000001','Synthetic planning contractor','Pacific/Auckland',null,null,null,null);
insert into public.profiles(id,company_id,role,full_name) values('e2100000-0000-4000-8000-000000000001','e2200000-0000-4000-8000-000000000001','owner','Synthetic owner'),('e2100000-0000-4000-8000-000000000002','e2200000-0000-4000-8000-000000000001','employee','Synthetic employee');
create temp table planning_results(key text primary key,id uuid);grant all on planning_results to authenticated;
select set_config('request.jwt.claim.sub','e2100000-0000-4000-8000-000000000001',true);set local role authenticated;
insert into planning_results values('project',public.carez_intake_external_job('e2300000-0000-4000-8000-000000000001','{"job_number":"SYN-EXT-PLAN","name":"Synthetic external planning job","customer_name":"Synthetic GC","agreement_reference":"SYN-EXT","agreement_evidence":"reported_signed_no_executed_copy","agreement_amount":10000,"external_proposal_amount":10000.12}'));
reset role;
insert into public.company_documents(id,company_id,project_id,document_type,title,storage_path,mime_type,source,review_status,created_by,content_sha256,byte_size,visibility,revision_label)
select 'e2400000-0000-4000-8000-000000000001','e2200000-0000-4000-8000-000000000001',id,'plan','Synthetic retained source','e2200000-0000-4000-8000-000000000001/sources/synthetic-only.pdf','application/pdf','external_intake','filed','e2100000-0000-4000-8000-000000000001',repeat('c',64),100,'job','R1' from planning_results where key='project';
set local role authenticated;
select extensions.lives_ok($$insert into planning_results values('set',public.carez_open_external_job_takeoff((select id from planning_results where key='project'),'e2400000-0000-4000-8000-000000000001'))$$,'unconfigured overhead does not prevent retained-source quantity planning');
select extensions.is(public.carez_open_external_job_takeoff((select id from planning_results where key='project'),'e2400000-0000-4000-8000-000000000001'),(select id from planning_results where key='set'),'reopen returns the exact existing set');
insert into planning_results select 'estimate',estimate_id from public.takeoff_sets where id=(select id from planning_results where key='set');
select extensions.ok((select status='draft' and overhead_snapshot_id is null and overhead_rate_snapshot is null from public.estimates where id=(select id from planning_results where key='estimate')),'missing basis remains a null pair on a draft');
select extensions.is((select count(*)::int from public.overhead_rate_snapshots),0,'planning does not invent an overhead snapshot');
select extensions.is((select count(*)::int from public.project_budgets),0,'opening source does not invent a budget');
select extensions.is((select count(*)::int from public.commercial_baselines),0,'opening source does not fabricate an accepted baseline');
select extensions.ok((select not job_ready from public.project_job_readiness_summary where project_id=(select id from planning_results where key='project')),'external agreement hold is preserved independently');
select extensions.ok(public.carez_get_estimate_release_readiness((select id from planning_results where key='estimate'))->'blockers' @> '[{"finding_key":"overhead_basis_unconfigured"}]','release readiness exposes the missing configured basis');
select extensions.throws_like($$update public.estimates set status='ready' where id=(select id from planning_results where key='estimate')$$,'%Configured overhead basis required%','raw ready transition cannot bypass configured basis');
select extensions.throws_like($$update public.estimates set status='approved' where id=(select id from planning_results where key='estimate')$$,'%Configured overhead basis required%','raw approval cannot bypass configured basis');
select extensions.throws_like($$select public.carez_attach_estimate_overhead('e2500000-0000-4000-8000-000000000001',id,updated_at) from public.estimates where id=(select id from planning_results where key='estimate')$$,'%Configure the complete business%','explicit attachment fails honestly before configuration');
select public.carez_save_company_plan('e2600000-0000-4000-8000-000000000001',0,'{"target_margin_percent":0,"planned_productive_hours_annual":2000,"owner_compensation_target_annual":0,"owner_planned_field_hours_annual":0,"owner_field_rate":0}');
create temp table planning_stale as select id,updated_at from public.estimates where id=(select id from planning_results where key='estimate');
update public.estimates set target_margin_percent=1 where id=(select id from planning_results where key='estimate');
select extensions.throws_like($$select public.carez_attach_estimate_overhead('e2500000-0000-4000-8000-000000000001',id,updated_at) from planning_stale$$,'%Estimate changed%','a pricing edit invalidates an older attachment form');
insert into public.overhead_items(id,company_id,category,name,amount,frequency,business_use_percent) values('e2700000-0000-4000-8000-000000000001','e2200000-0000-4000-8000-000000000001','Synthetic','Invalid local fixture',-1,'annual',100);
select extensions.throws_like($$select public.carez_capture_overhead_v2(public.carez_company_calendar_date('e2200000-0000-4000-8000-000000000001',clock_timestamp()))$$,'%active overhead item has missing or invalid%','the exact aggregated input set rejects an invalid item');
update public.overhead_items set active=false where id='e2700000-0000-4000-8000-000000000001';
create temp table planning_attach as select id,updated_at from public.estimates where id=(select id from planning_results where key='estimate');
select extensions.lives_ok($$select public.carez_attach_estimate_overhead('e2500000-0000-4000-8000-000000000001',id,updated_at) from planning_attach$$,'configured zero explicitly attaches to the editable draft');
select extensions.ok((select overhead_snapshot_id is not null and overhead_rate_snapshot=0 from public.estimates where id=(select id from planning_results where key='estimate')),'configured zero has its own immutable snapshot identity');
select extensions.lives_ok($$select public.carez_attach_estimate_overhead('e2500000-0000-4000-8000-000000000001',id,updated_at) from planning_attach$$,'confirmed attachment retry survives updated estimate state');
select extensions.throws_like($$select public.carez_attach_estimate_overhead('e2500000-0000-4000-8000-000000000002',id,updated_at) from planning_attach$$,'%Estimate changed%','another request cannot overwrite a stale estimate basis');
select extensions.ok(not(public.carez_get_estimate_release_readiness((select id from planning_results where key='estimate'))->'blockers' @> '[{"finding_key":"overhead_basis_unconfigured"}]'),'configured zero clears only the overhead blocker');
select extensions.lives_ok($$update public.estimates set status='ready' where id=(select id from planning_results where key='estimate')$$,'configured zero allows the ready stage without approving other release checks');
select extensions.is((select effective_date from public.overhead_rate_snapshots),public.carez_company_calendar_date('e2200000-0000-4000-8000-000000000001',clock_timestamp()),'new capture uses operating calendar day');
select public.carez_save_company_plan('e2600000-0000-4000-8000-000000000002',1,'{"target_margin_percent":0,"planned_productive_hours_annual":2000,"owner_compensation_target_annual":100000,"owner_planned_field_hours_annual":0,"owner_field_rate":0}');
select extensions.is(public.carez_open_external_job_takeoff((select id from planning_results where key='project'),'e2400000-0000-4000-8000-000000000001'),(select id from planning_results where key='set'),'reopen never auto-refreshes the pinned estimate basis');
select extensions.is((select overhead_rate_snapshot from public.estimates where id=(select id from planning_results where key='estimate')),0::numeric,'later company changes do not rewrite recorded estimate assumptions');
select set_config('request.jwt.claim.sub','e2100000-0000-4000-8000-000000000002',true);
select extensions.throws_like($$select public.carez_open_external_job_takeoff((select id from planning_results where key='project'),'e2400000-0000-4000-8000-000000000001')$$,'%Owner or office%','employee cannot open company pricing through external intake');
select extensions.throws_like($$select public.carez_attach_estimate_overhead('e2500000-0000-4000-8000-000000000003',(select id from planning_results where key='estimate'),now())$$,'%Owner or office authority%','employee cannot attach company financial assumptions');
select * from extensions.finish();rollback;
